import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Pricing card node for hub-pricing.
 * Renders a textured plane with baked gradient and grain.
 * No interactivity, no cinematic primitives.
 */
export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Container
  const group = new THREE.Group();

  // Geometry – derived from atlas source rect aspect ratio (512×320 ≈ 1.6:1)
  const width = 2.0;
  const height = width * (320 / 512); // ≈1.25
  const geometry = new THREE.PlaneGeometry(width, height);

  // Material – BasicNodeMaterial, map loaded async
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // surface fallback
    side: THREE.DoubleSide,
    transparent: false,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load texture
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    }).catch(() => {
      // fallback – gradient could be generated procedurally but spec says static composition
    });
  }

  // Handlers (none for this static card)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    material.dispose();
    geometry.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
